import React, { useState, useEffect } from 'react';
import axios from 'axios';

const StudentManagement = () => {
  const [students, setStudents] = useState([]);
  const [filteredStudents, setFilteredStudents] = useState([]);
  const [formData, setFormData] = useState({
    studentId: '',
    name: '',
    email: '',
    phone: '',
    gender: 'Male', // New: Added gender field
    age: '', // New: Added age field
    studentClass: ''
  });
  const [searchTerm, setSearchTerm] = useState(''); // New: State for search term
  const [genderFilter, setGenderFilter] = useState('All'); // New: State for gender filter
  const [classFilter, setClassFilter] = useState('All'); // New: State for class filter

  const { studentId, name, email, phone, gender, age, studentClass } = formData;

  useEffect(() => {
    fetchStudents();
  }, []);

  useEffect(() => {
    let filtered = students;

    // Apply gender filter
    if (genderFilter !== 'All') {
      filtered = filtered.filter(student => student.gender === genderFilter);
    }

    // Apply class filter
    if (classFilter !== 'All') {
      filtered = filtered.filter(student => student.class === classFilter);
    }

    // Apply search filter (by studentId)
    if (searchTerm) {
      filtered = filtered.filter(student =>
        student.studentId.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    setFilteredStudents(filtered);
  }, [students, genderFilter, classFilter, searchTerm]);

  const fetchStudents = async () => {
    try {
      const token = localStorage.getItem('token');
      const res = await axios.get('http://localhost:5000/api/students', {
        headers: { 'x-auth-token': token }
      });
      setStudents(res.data);
    } catch (err) {
      console.error(err);
      alert('Could not fetch students. Please log in again.');
    }
  };

  const onChange = e => setFormData({ ...formData, [e.target.name]: e.target.value });

  const onSubmit = async e => {
    e.preventDefault();
    try {
      const token = localStorage.getItem('token');
      await axios.post('http://localhost:5000/api/students', formData, {
        headers: { 'x-auth-token': token }
      });
      fetchStudents();
      setFormData({ studentId: '', name: '', email: '', phone: '', gender: 'Male', age: '', studentClass: '' });
    } catch (err) {
      console.error(err.response.data);
      alert('Failed to add student. Check the console for details.');
    }
  };

  // Helper function for summary counts
  const totalStudents = students.length;
  const totalBoys = students.filter(student => student.gender === 'Male').length;
  const totalGirls = students.filter(student => student.gender === 'Female').length;

  return (
    <div>
      <h2>Student Management</h2>

      {/* Student Summary Section */}
      <div className="summary-section">
        <h3>Total Students: {totalStudents}</h3>
        <p>Boys: {totalBoys}</p>
        <p>Girls: {totalGirls}</p>
      </div>

      <hr />

      {/* Add Student Form */}
      <h3>Add New Student</h3>
      <form onSubmit={onSubmit}>
        <input type="text" name="studentId" value={studentId} onChange={onChange} placeholder="Student ID" required />
        <input type="text" name="name" value={name} onChange={onChange} placeholder="Name" required />
        <input type="email" name="email" value={email} onChange={onChange} placeholder="Email" required />
        <input type="text" name="phone" value={phone} onChange={onChange} placeholder="Phone" />

        <select name="gender" value={gender} onChange={onChange} required>
          <option value="Male">Male</option>
          <option value="Female">Female</option>
        </select>

        <input type="number" name="age" value={age} onChange={onChange} placeholder="Age" required />
        <input type="text" name="studentClass" value={studentClass} onChange={onChange} placeholder="Class" required />
        <button type="submit">Add Student</button>
      </form>

      <hr />

      {/* Student List and Filters Section */}
      <h3>Student List</h3>
      <div className="controls-container">
        {/* Search Bar */}
        <input 
          type="text" 
          placeholder="Search by Student ID..." 
          value={searchTerm} 
          onChange={e => setSearchTerm(e.target.value)}
        />

        {/* Filter Options */}
        <select value={genderFilter} onChange={e => setGenderFilter(e.target.value)}>
          <option value="All">All Genders</option>
          <option value="Male">Male</option>
          <option value="Female">Female</option>
        </select>

        <select value={classFilter} onChange={e => setClassFilter(e.target.value)}>
          <option value="All">All Classes</option>
          {/* Dynamically generate class options from student data */}
          {[...new Set(students.map(s => s.class))].map(c => (
            <option key={c} value={c}>{c}</option>
          ))}
        </select>
      </div>

      <table>
        <thead>
          <tr>
            <th>Student ID</th>
            <th>Name</th>
            <th>Email</th>
            <th>Phone</th>
            <th>Gender</th>
            <th>Age</th>
            <th>Class</th>
          </tr>
        </thead>
        <tbody>
          {filteredStudents.map(student => (
            <tr key={student._id}>
              <td>{student.studentId}</td>
              <td>{student.name}</td>
              <td>{student.email}</td>
              <td>{student.phone}</td>
              <td>{student.gender}</td>
              <td>{student.age}</td>
              <td>{student.class}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default StudentManagement;
